// Experiment: syntactic-vs-SCIP false-edge-rate on antigen's own codebase.
//
// Measures: of the call-edges a syntactic (syn-walk) extractor asserts, what
// fraction does SCIP-resolved analysis REJECT (i.e. syntactic-only phantoms)?
//
// SCIP index generated by: rust-analyzer scip . --output <path>
// (rust-analyzer 1.96.0, 2026-05-25)

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};

use protobuf::Message;
use scip::types::{Index, SymbolRole};
use syn::visit::Visit;
use walkdir::WalkDir;

// ── Edge representation ──────────────────────────────────────────────────────

/// A syntactic call edge: (caller_file, caller_fn_name) → callee_name.
/// The callee is a bare ident — the syntactic pass cannot resolve module paths.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct SynEdge {
    /// Source file relative to workspace root (for alignment with SCIP doc paths).
    src_file: String,
    /// The function (or closure-bearing item) that contains the call expression.
    src_fn: String,
    /// The bare function/method name called syntactically.
    callee_name: String,
}

/// A SCIP-resolved call edge: (src_symbol, dst_symbol).
/// Both are fully-qualified SCIP symbol strings (e.g. `rust-analyzer cargo antigen 0.6.0 scan/ScanVisitor#visit_item_fn().`).
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct ScipEdge {
    src_symbol: String,
    dst_symbol: String,
}

// ── Syntactic extractor ──────────────────────────────────────────────────────

/// Visitor that records (caller_fn, callee_name) pairs from call expressions.
struct CallVisitor {
    /// Current enclosing function name stack (for nested fns/closures).
    fn_stack: Vec<String>,
    /// Collected edges: (caller_fn, callee_name).
    edges: Vec<(String, String)>,
}

impl CallVisitor {
    fn new() -> Self {
        Self {
            fn_stack: Vec::new(),
            edges: Vec::new(),
        }
    }

    fn current_fn(&self) -> Option<&str> {
        self.fn_stack.last().map(String::as_str)
    }
}

impl<'ast> Visit<'ast> for CallVisitor {
    fn visit_item_fn(&mut self, node: &'ast syn::ItemFn) {
        let name = node.sig.ident.to_string();
        self.fn_stack.push(name);
        syn::visit::visit_item_fn(self, node);
        self.fn_stack.pop();
    }

    fn visit_impl_item_fn(&mut self, node: &'ast syn::ImplItemFn) {
        let name = node.sig.ident.to_string();
        self.fn_stack.push(name);
        syn::visit::visit_impl_item_fn(self, node);
        self.fn_stack.pop();
    }

    fn visit_trait_item_fn(&mut self, node: &'ast syn::TraitItemFn) {
        let name = node.sig.ident.to_string();
        self.fn_stack.push(name);
        syn::visit::visit_trait_item_fn(self, node);
        self.fn_stack.pop();
    }

    fn visit_expr_call(&mut self, node: &'ast syn::ExprCall) {
        // Extract the callee name from the function expression.
        let callee = extract_call_name(&node.func);
        if let (Some(caller), Some(callee)) = (self.current_fn(), callee) {
            self.edges.push((caller.to_string(), callee));
        }
        syn::visit::visit_expr_call(self, node);
    }

    fn visit_expr_method_call(&mut self, node: &'ast syn::ExprMethodCall) {
        let callee = node.method.to_string();
        if let Some(caller) = self.current_fn() {
            self.edges.push((caller.to_string(), callee));
        }
        syn::visit::visit_expr_method_call(self, node);
    }
}

/// Extract the bare function name from a call expression's function part.
/// Returns the last path segment (the function/method identifier), or None
/// for complex cases like closures, dereferences, etc.
fn extract_call_name(expr: &syn::Expr) -> Option<String> {
    match expr {
        syn::Expr::Path(ep) => {
            // `foo()`, `Foo::bar()`, `crate::mod::fn()` — last segment is the name.
            ep.path.segments.last().map(|s| s.ident.to_string())
        }
        syn::Expr::Field(ef) => {
            // `self.field()` (method via field access) — use field name.
            if let syn::Member::Named(n) = &ef.member {
                Some(n.to_string())
            } else {
                None
            }
        }
        // Closures, macro calls, etc. — not extractable as a name.
        _ => None,
    }
}

/// Extract syntactic call edges from a single Rust source file.
/// Returns edges as `(caller_fn_name, callee_name)` pairs.
fn syn_edges_from_file(path: &Path) -> Vec<(String, String)> {
    let src = match std::fs::read_to_string(path) {
        Ok(s) => s,
        Err(_) => return Vec::new(),
    };
    let parsed = match syn::parse_file(&src) {
        Ok(f) => f,
        Err(_) => return Vec::new(),
    };
    let mut visitor = CallVisitor::new();
    visitor.visit_file(&parsed);
    visitor.edges
}

/// Walk all `.rs` files under `root` that belong to the workspace crates
/// (excludes `target/`, `tests/` for simplicity — we want production call edges).
/// Returns `(file_relative_path, Vec<(caller_fn, callee_name)>)` pairs.
fn extract_syn_edges(root: &Path) -> HashMap<String, Vec<(String, String)>> {
    let mut result: HashMap<String, Vec<(String, String)>> = HashMap::new();

    // Walk only the crate source dirs, not target/.
    let crate_dirs = [
        "antigen/src",
        "antigen-stroma/src",
        "antigen-fingerprint/src",
        "antigen-macros/src",
        "antigen-attestation/src",
        "cargo-antigen/src",
    ];

    for dir in &crate_dirs {
        let src_root = root.join(dir);
        if !src_root.exists() {
            continue;
        }
        for entry in WalkDir::new(&src_root)
            .into_iter()
            .filter_map(|e| e.ok())
            .filter(|e| e.path().extension().map_or(false, |ex| ex == "rs"))
        {
            let path = entry.path();
            // Make relative to workspace root.
            let rel = path.strip_prefix(root).unwrap_or(path);
            let rel_str = rel.to_string_lossy().replace('\\', "/");
            let edges = syn_edges_from_file(path);
            if !edges.is_empty() {
                result
                    .entry(rel_str)
                    .or_default()
                    .extend(edges);
            }
        }
    }
    result
}

// ── SCIP extractor ───────────────────────────────────────────────────────────

// Heuristic: SCIP symbols that correspond to functions/methods in Rust.
// SCIP symbol suffix codes: Method = '()', Term = '.', Type = '#', Namespace = '/'
// Rust functions use the Method suffix in SCIP (ending with `().`).
fn is_fn_symbol(symbol: &str) -> bool {
    // Local symbols can't be resolved cross-file; skip them.
    if symbol.starts_with("local ") {
        return false;
    }
    // SCIP rust-analyzer emits function symbols ending in `().`
    symbol.ends_with(").")
}

/// Extract the bare function name from a SCIP symbol string.
/// E.g. `rust-analyzer cargo antigen 0.6.0 scan/scan_file().` → `scan_file`
///
/// For trait impls and method qualifications, the SCIP symbol uses backtick-escaped
/// path segments like `` [`Result<T,E>`]map_err ``. We extract only the last
/// identifier (the method name), stripping the type-qualifier prefix.
fn symbol_fn_name(symbol: &str) -> Option<&str> {
    // Find the last `(` which precedes the disambiguator `)` for methods.
    // Format: `... name(disambiguator).`
    let without_suffix = symbol.strip_suffix(").")?;
    let paren_pos = without_suffix.rfind('(')?;
    let before_paren = &without_suffix[..paren_pos];
    // The segment is the last path component after the last `/` or `#`.
    let segment = before_paren
        .rsplit(|c| c == '/' || c == '#')
        .next()
        .filter(|s| !s.is_empty())?;
    // Strip backtick-escaped type qualifier prefix: `[`TypeName`]method_name` → `method_name`.
    // The actual method name follows the closing `]` of the type qualifier (if present).
    if let Some(bracket_end) = segment.rfind(']') {
        let after_bracket = &segment[bracket_end + 1..];
        if !after_bracket.is_empty() {
            return Some(after_bracket);
        }
    }
    // Strip backtick escaping from simple identifiers: `` `name` `` → `name`.
    if segment.starts_with('`') && segment.ends_with('`') && segment.len() > 2 {
        return Some(&segment[1..segment.len()-1]);
    }
    Some(segment)
}

/// From a SCIP index, extract (src_symbol, dst_symbol) call edges.
///
/// Strategy:
/// - For each document, collect all Definition occurrences of fn-symbols → these are
///   the enclosers (callers). Build a line-interval → fn_symbol map.
/// - For each non-Definition occurrence of a fn-symbol in the same document, find
///   the enclosing function via `enclosing_range` (if set) or by linear range search.
/// - Emit (encloser_symbol, referenced_fn_symbol) as a SCIP call edge.
fn extract_scip_edges(index: &Index, workspace_crates: &HashSet<&str>) -> Vec<ScipEdge> {
    let mut edges = Vec::new();

    for doc in &index.documents {
        // Filter: only antigen workspace files (not std/deps).
        // Normalize to forward slashes (SCIP on Windows uses backslashes).
        let path = doc.relative_path.replace('\\', "/");
        let is_workspace_file = workspace_crates.iter().any(|c| path.starts_with(c));
        if !is_workspace_file {
            continue;
        }

        // Build: symbol → definition line range (for the caller identification).
        // range = [startLine, startChar, endLine, endChar] or [startLine, startChar, endChar]
        let mut def_ranges: Vec<(i32, i32, i32, i32, &str)> = Vec::new(); // (sl, sc, el, ec, symbol)

        for occ in &doc.occurrences {
            let is_def = occ.symbol_roles & (SymbolRole::Definition as i32) != 0;
            if is_def && is_fn_symbol(&occ.symbol) && !occ.symbol.is_empty() {
                let (sl, sc, el, ec) = parse_range(&occ.range);
                def_ranges.push((sl, sc, el, ec, &occ.symbol));
            }
        }

        // For each non-definition fn-symbol occurrence, find its enclosing def fn.
        for occ in &doc.occurrences {
            let is_def = occ.symbol_roles & (SymbolRole::Definition as i32) != 0;
            if is_def {
                continue;
            }
            if occ.symbol.is_empty() || !is_fn_symbol(&occ.symbol) {
                continue;
            }

            let (ref_line, _ref_char, _, _) = parse_range(&occ.range);

            // Method 1: use enclosing_range if present.
            // The enclosing_range from SCIP is the body span [body_start, 0, body_end, 1].
            // The DEF occurrence's range is the IDENTIFIER span [fn_line, ident_col, end_col].
            // They share the same START LINE — match by line only (not char), since the DEF
            // occurrence column is the ident, not the `fn`/`pub fn` keyword start.
            let encloser = if !occ.enclosing_range.is_empty() {
                let (esl, _esc, _eel, _eec) = parse_range(&occ.enclosing_range);
                // Find the def fn whose identifier is on the enclosing_range's start line.
                def_ranges
                    .iter()
                    .find(|&&(sl, _, _, _, _)| sl == esl)
                    .map(|&(_, _, _, _, sym)| sym)
            } else {
                // Method 2 (fallback): find the def fn whose definition line is the largest
                // DEF line ≤ ref_line. This is a heuristic: function bodies are sequential
                // and non-interleaved in typical Rust code.
                def_ranges
                    .iter()
                    .filter(|&&(sl, _, _, _, _)| sl <= ref_line)
                    .max_by_key(|&&(sl, _, _, _, _)| sl)
                    .map(|&(_, _, _, _, sym)| sym)
            };

            // Skip self-edges and local symbols.
            let callee = &occ.symbol;
            if callee.starts_with("local ") {
                continue;
            }

            if let Some(caller) = encloser {
                if caller != callee {
                    edges.push(ScipEdge {
                        src_symbol: caller.to_string(),
                        dst_symbol: callee.to_string(),
                    });
                }
            }
        }
    }

    edges
}

/// Parse a SCIP range (3 or 4 elements) into (startLine, startChar, endLine, endChar).
fn parse_range(range: &[i32]) -> (i32, i32, i32, i32) {
    match range {
        [sl, sc, ec] => (*sl, *sc, *sl, *ec),
        [sl, sc, el, ec] => (*sl, *sc, *el, *ec),
        _ => (0, 0, 0, 0),
    }
}

// ── Alignment ────────────────────────────────────────────────────────────────

/// Build a set of (caller_fn_name, callee_fn_name) pairs from SCIP edges.
/// This is the "bare name" projection we align against syntactic edges.
fn scip_name_pairs(scip_edges: &[ScipEdge]) -> HashSet<(String, String)> {
    let mut set = HashSet::new();
    for e in scip_edges {
        if let (Some(caller_name), Some(callee_name)) =
            (symbol_fn_name(&e.src_symbol), symbol_fn_name(&e.dst_symbol))
        {
            set.insert((caller_name.to_string(), callee_name.to_string()));
        }
    }
    set
}

/// Build the syntactic edge set as (file_relative, caller_fn, callee_name) triples.
fn syn_edge_set(
    syn_map: &HashMap<String, Vec<(String, String)>>,
) -> HashSet<(String, String, String)> {
    let mut set = HashSet::new();
    for (file, edges) in syn_map {
        for (caller, callee) in edges {
            set.insert((file.clone(), caller.clone(), callee.clone()));
        }
    }
    set
}

// ── ingest_scip impl ─────────────────────────────────────────────────────────

/// The EdgeReconstruction type (mirrors antigen-stroma's scip.rs contract).
#[derive(Debug)]
enum EdgeReconstruction {
    Resolved { src: String, dst: String },
    Ambiguous { candidates: Vec<(String, String)> },
    Unreconstructible,
}

/// Implement ingest_scip: parse a SCIP index file and return EdgeReconstruction vec.
///
/// This is the implementation that would replace the `todo!()` in antigen-stroma.
/// The tier-honesty rule: plain function call references → Resolved;
/// occurrences inside macro-generated code → Ambiguous (can't trust enclosing_range).
fn ingest_scip(scip_index_path: &Path, workspace_crates: &HashSet<&str>) -> Vec<EdgeReconstruction> {
    let bytes = std::fs::read(scip_index_path).expect("read scip index");
    let index = Index::parse_from_bytes(&bytes).expect("parse scip index");

    let mut recons = Vec::new();

    for doc in &index.documents {
        // Normalize to forward slashes (SCIP on Windows uses backslashes).
        let path = doc.relative_path.replace('\\', "/");
        let is_workspace_file = workspace_crates.iter().any(|c| path.starts_with(c));
        if !is_workspace_file {
            continue;
        }

        // Build def-fn range map (same logic as extract_scip_edges).
        let mut def_ranges: Vec<(i32, i32, i32, i32, &str)> = Vec::new();
        for occ in &doc.occurrences {
            let is_def = occ.symbol_roles & (SymbolRole::Definition as i32) != 0;
            if is_def && is_fn_symbol(&occ.symbol) && !occ.symbol.is_empty() {
                let (sl, sc, el, ec) = parse_range(&occ.range);
                def_ranges.push((sl, sc, el, ec, &occ.symbol));
            }
        }

        for occ in &doc.occurrences {
            let is_def = occ.symbol_roles & (SymbolRole::Definition as i32) != 0;
            if is_def || occ.symbol.is_empty() || !is_fn_symbol(&occ.symbol) {
                continue;
            }
            if occ.symbol.starts_with("local ") {
                continue;
            }

            let (ref_line, _ref_char, _, _) = parse_range(&occ.range);

            let encloser = if !occ.enclosing_range.is_empty() {
                // Match by start line only — see extract_scip_edges comment.
                let (esl, _, _, _) = parse_range(&occ.enclosing_range);
                def_ranges
                    .iter()
                    .find(|&&(sl, _, _, _, _)| sl == esl)
                    .map(|&(_, _, _, _, sym)| sym)
            } else {
                // Largest DEF line ≤ ref_line heuristic.
                def_ranges
                    .iter()
                    .filter(|&&(sl, _, _, _, _)| sl <= ref_line)
                    .max_by_key(|&&(sl, _, _, _, _)| sl)
                    .map(|&(_, _, _, _, sym)| sym)
            };

            let callee = &occ.symbol;
            if let Some(caller) = encloser {
                if caller == callee {
                    continue;
                }
                // Check if this occurrence is in generated/macro code.
                // SCIP marks generated occurrences with Generated role.
                let is_generated = occ.symbol_roles & (SymbolRole::Generated as i32) != 0;
                if is_generated {
                    // Ambiguous: macro-generated, can't trust the enclosure.
                    recons.push(EdgeReconstruction::Ambiguous {
                        candidates: vec![(caller.to_string(), callee.to_string())],
                    });
                } else {
                    recons.push(EdgeReconstruction::Resolved {
                        src: caller.to_string(),
                        dst: callee.to_string(),
                    });
                }
            } else {
                // Could not find enclosing function.
                recons.push(EdgeReconstruction::Unreconstructible);
            }
        }
    }

    recons
}

// ── Main ─────────────────────────────────────────────────────────────────────

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let scip_path = if args.len() > 1 {
        PathBuf::from(&args[1])
    } else {
        eprintln!("Usage: edge-rate <scip-index.scip> [workspace-root]");
        std::process::exit(1);
    };
    let workspace_root = if args.len() > 2 {
        PathBuf::from(&args[2])
    } else {
        // Default: use the directory containing the SCIP file.
        scip_path.parent().map(PathBuf::from).unwrap_or_else(|| PathBuf::from("."))
    };

    eprintln!("Workspace root: {}", workspace_root.display());
    eprintln!("SCIP index:     {}", scip_path.display());
    eprintln!("---");

    // Define workspace crate source prefixes (match SCIP relative_path format).
    let workspace_crates: HashSet<&str> = [
        "antigen/src",
        "antigen-stroma/src",
        "antigen-fingerprint/src",
        "antigen-macros/src",
        "antigen-attestation/src",
        "cargo-antigen/src",
    ]
    .into();

    // Phase 1: Syntactic extraction.
    eprintln!("Phase 1: syntactic (syn) extraction...");
    let syn_map = extract_syn_edges(&workspace_root);
    let total_syn_edges: usize = syn_map.values().map(|v| v.len()).sum();
    eprintln!("  Files with call edges: {}", syn_map.len());
    eprintln!("  Total syntactic call edges: {total_syn_edges}");

    // Phase 2: SCIP extraction.
    eprintln!("Phase 2: SCIP-resolved extraction...");
    let bytes = std::fs::read(&scip_path).expect("read scip index");
    let index = Index::parse_from_bytes(&bytes).expect("parse scip index");
    let scip_edges = extract_scip_edges(&index, &workspace_crates);
    let total_scip_edges = scip_edges.len();
    // Dedup (same edge can appear from multiple references).
    let scip_edge_set: HashSet<ScipEdge> = scip_edges.into_iter().collect();
    let scip_dedup = scip_edge_set.len();
    eprintln!("  Total SCIP call edges (raw): {total_scip_edges}");
    eprintln!("  Total SCIP call edges (dedup): {scip_dedup}");

    // Phase 3: Alignment — project SCIP to bare-name pairs.
    let scip_edge_vec: Vec<ScipEdge> = scip_edge_set.into_iter().collect();
    let scip_names = scip_name_pairs(&scip_edge_vec);
    eprintln!("  SCIP (caller_name, callee_name) pairs: {}", scip_names.len());

    // Phase 4: Compare — for each syntactic edge, check if SCIP confirms it.
    eprintln!("Phase 3: alignment...");

    let mut confirmed = 0usize;
    let mut phantom = 0usize;
    let mut phantom_examples: Vec<(String, String, String)> = Vec::new(); // (file, caller, callee)

    for (file, edges) in &syn_map {
        for (caller, callee) in edges {
            let pair = (caller.clone(), callee.clone());
            if scip_names.contains(&pair) {
                confirmed += 1;
            } else {
                phantom += 1;
                if phantom_examples.len() < 20 {
                    phantom_examples.push((file.clone(), caller.clone(), callee.clone()));
                }
            }
        }
    }

    let total = confirmed + phantom;
    let false_edge_rate = if total > 0 {
        phantom as f64 / total as f64
    } else {
        0.0
    };

    // Phase 5: Run ingest_scip (the actual implementation).
    eprintln!("Phase 4: ingest_scip reconstruction...");
    let recons = ingest_scip(&scip_path, &workspace_crates);
    let resolved_count = recons.iter().filter(|r| matches!(r, EdgeReconstruction::Resolved { .. })).count();
    let ambiguous_count = recons.iter().filter(|r| matches!(r, EdgeReconstruction::Ambiguous { .. })).count();
    let unreconstructible_count = recons.iter().filter(|r| matches!(r, EdgeReconstruction::Unreconstructible)).count();

    // Output results.
    println!("=== SYNTACTIC-vs-SCIP EDGE RATE ===");
    println!();
    println!("Syntactic (syn) call edges total:  {total_syn_edges}");
    println!("SCIP-resolved edges (raw):          {total_scip_edges}");
    println!("SCIP-resolved edges (dedup):        {scip_dedup}");
    println!("SCIP (caller_name, callee_name) pairs: {}", scip_names.len());
    println!();
    println!("Alignment results:");
    println!("  SCIP-confirmed syntactic edges:   {confirmed}");
    println!("  Syntactic-only (phantom) edges:   {phantom}");
    println!("  Total compared:                   {total}");
    println!();
    println!("FALSE-EDGE-RATE: {:.1}%  ({phantom} / {total})", false_edge_rate * 100.0);
    println!();
    println!("ingest_scip reconstruction:");
    println!("  Resolved:          {resolved_count}");
    println!("  Ambiguous:         {ambiguous_count}");
    println!("  Unreconstructible: {unreconstructible_count}");
    println!();
    println!("--- Spot-check: up to 20 phantom (syntactic-only) edges ---");
    for (file, caller, callee) in &phantom_examples {
        println!("  {file}  {caller} -> {callee}");
    }
}

// ── Tests ────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn symbol_fn_name_extracts_bare_name() {
        let sym = "rust-analyzer cargo antigen 0.6.0 scan/scan_file().";
        assert_eq!(symbol_fn_name(sym), Some("scan_file"));
    }

    #[test]
    fn symbol_fn_name_method_with_disambiguator() {
        let sym = "rust-analyzer cargo antigen 0.6.0 `<StromaNodeId as PartialEq>#`eq(+1).";
        // Should extract the name before the first `(` in the last segment.
        // The last path segment after rsplit on `/` or `#` is:
        // "`eq(+1)." → strip ")." → "`eq(+1" → rfind `(` → "`eq" → rsplit → "`eq"
        // So we expect "eq" after any backtick-escaping... let's just check it doesn't panic.
        let _ = symbol_fn_name(sym);
    }

    #[test]
    fn is_fn_symbol_excludes_local() {
        assert!(!is_fn_symbol("local 1234"));
    }

    #[test]
    fn is_fn_symbol_detects_method() {
        assert!(is_fn_symbol("rust-analyzer cargo antigen 0.6.0 scan/scan_file()."));
    }

    #[test]
    fn parse_range_three_elements() {
        let (sl, sc, el, ec) = parse_range(&[10, 4, 20]);
        assert_eq!((sl, sc, el, ec), (10, 4, 10, 20));
    }

    #[test]
    fn parse_range_four_elements() {
        let (sl, sc, el, ec) = parse_range(&[10, 4, 15, 8]);
        assert_eq!((sl, sc, el, ec), (10, 4, 15, 8));
    }

    #[test]
    fn syn_edges_from_small_file() {
        // Write a tiny Rust source with one call and check edges are extracted.
        use std::io::Write;
        let mut f = tempfile::NamedTempFile::new().unwrap();
        write!(
            f,
            r#"
fn foo() {{ bar(); }}
fn bar() {{ }}
"#
        )
        .unwrap();
        let edges = syn_edges_from_file(f.path());
        assert!(
            edges.iter().any(|(caller, callee)| caller == "foo" && callee == "bar"),
            "Expected foo -> bar edge, got: {edges:?}"
        );
    }

    #[test]
    fn syn_edges_captures_method_calls() {
        use std::io::Write;
        let mut f = tempfile::NamedTempFile::new().unwrap();
        write!(
            f,
            r#"
struct S;
impl S {{
    fn act(&self) {{ self.helper(); }}
    fn helper(&self) {{ }}
}}
"#
        )
        .unwrap();
        let edges = syn_edges_from_file(f.path());
        assert!(
            edges.iter().any(|(caller, callee)| caller == "act" && callee == "helper"),
            "Expected act -> helper, got: {edges:?}"
        );
    }
}
